export const getListContractsUrl = (weddingId: number,) => {




  return `/api/weddings/${weddingId}/contracts`
}

/**
 * @summary List contracts for a wedding
 */
export const listContracts = async (weddingId: number, options?: Parameters<typeof customFetch>[1]): Promise<Contract[]> => {

  return customFetch<Contract[]>(getListContractsUrl(weddingId),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListContractsQueryKey = (weddingId: number,) => {
    return [
    `/api/weddings/${weddingId}/contracts`
    ] as const;
    }


export const getListContractsQueryOptions = <TData = Awaited<ReturnType<typeof listContracts>>, TError = ErrorType<unknown>>(weddingId: number, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listContracts>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListContractsQueryKey(weddingId);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listContracts>>> = ({ signal }) => listContracts(weddingId, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: weddingId !== null && weddingId !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listContracts>>, TError, TData> & { queryKey: QueryKey }
}

export type ListContractsQueryResult = NonNullable<Awaited<ReturnType<typeof listContracts>>>
export type ListContractsQueryError = ErrorType<unknown>


/**
 * @summary List contracts for a wedding
 */

export function useListContracts<TData = Awaited<ReturnType<typeof listContracts>>, TError = ErrorType<unknown>>(
 weddingId: number, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listContracts>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getListContractsQueryOptions(weddingId,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







export const getCreateContractUrl = (weddingId: number,) => {




  return `/api/weddings/${weddingId}/contracts`
}

/**
 * @summary Add a contract
 */
export const createContract = async (weddingId: number,
    contractInput: ContractInput, options?: Parameters<typeof customFetch>[1]): Promise<Contract> => {

  return customFetch<Contract>(getCreateContractUrl(weddingId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(contractInput)
  }
);}





